        <td>¥${(product.単価 || 0).toLocaleString()}</td>
        <td>${product.発注単位 || 0}</td>
        <td>
          <button class="action-btn secondary select-product-btn" data-id="${product.id}">選択</button>
        </td>
      </tr>
    `).join('');

    resultsDiv.style.display = 'block';
  }

  // 商品選択表示
  function showSelectedProduct(product) {
    selectedProduct = product;
    const productDiv = container.querySelector('#selected-product');
    const productInfo = container.querySelector('#product-info');

    productInfo.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px;">
        <div><strong>商品コード:</strong> ${product.商品コード || ''}</div>
        <div><strong>商品名:</strong> ${product.商品名 || ''}</div>
        <div><strong>単価:</strong> ¥${(product.単価 || 0).toLocaleString()}</div>
        <div><strong>発注単位:</strong> ${product.発注単位 || 0}</div>
        <div><strong>最小発注数量:</strong> ${product.最小発注数量 || 0}</div>
        <div><strong>リードタイム:</strong> ${product.リードタイム日数 || 0}日</div>
      </div>
    `;

    productDiv.style.display = 'block';

    // リードタイムを自動設定
    container.querySelector('#lead-time').value = product.リードタイム日数 || 7;
  }

  // AI予測結果表示
  function showPredictionResult(prediction) {
    predictionData = prediction;
    const predictionDiv = container.querySelector('#prediction-result');
    const predictionInfo = container.querySelector('#prediction-info');

    predictionInfo.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px;">
        <div><strong>予測数量:</strong> ${prediction.予測数量 || 0}個</div>
        <div><strong>予測精度:</strong> ${prediction.予測精度 || 0}%</div>
        <div><strong>推奨発注数量:</strong> ${prediction.推奨発注数量 || 0}個</div>
        <div><strong>予測対象日:</strong> ${prediction.予測対象日 ? new Date(prediction.予測対象日).toLocaleDateString() : ''}</div>
      </div>
    `;

    predictionDiv.style.display = 'block';
  }

  // 発注量計算
  function calculateOrderQuantity() {
    if (!selectedProduct) {
      showError('商品を選択してください');
      return;
    }

    const currentStock = parseInt(container.querySelector('#current-stock').value) || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 7;
    const weatherImpact = parseInt(container.querySelector('#weather-impact').value) || 100;
    const eventImpact = parseInt(container.querySelector('#event-impact').value) || 100;
    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value) || 1.0;

    // バリデーション
    if (currentStock < 0) {
      showError('在庫数は0以上の値を入力してください');
      return;
    }

    if (leadTime < 1 || leadTime > 365) {
      showError('リードタイムは1日以上365日以下で入力してください');
      return;
    }

    if (seasonalFactor < 0.1 || seasonalFactor > 10) {
      showError('季節補正係数は0.1以上10以下で入力してください');
      return;
    }

    // 基本需要予測（予測データがあれば使用、なければデフォルト値）
    const baseDemand = predictionData ? predictionData.予測数量 : 100;

    // 影響度調整適用
    const adjustedDemand = baseDemand * (weatherImpact / 100) * (eventImpact / 100) * seasonalFactor;

    // リードタイム期間の需要
    const leadTimeDemand = adjustedDemand * (leadTime / 7); // 週単位で計算

    // 発注量計算: (リードタイム期間需要 + 安全在庫) - 現在在庫
    const orderQuantity = Math.max(0, Math.ceil(leadTimeDemand + safetyStock - currentStock));

    // 発注単位で調整
    const orderUnit = selectedProduct.発注単位 || 1;
    const adjustedOrderQuantity = Math.ceil(orderQuantity / orderUnit) * orderUnit;

    // 最小発注数量チェック
    const minOrderQty = selectedProduct.最小発注数量 || 0;
    const finalOrderQuantity = Math.max(adjustedOrderQuantity, minOrderQty);

    // 結果表示
    const resultDiv = container.querySelector('#calculation-result');
    const aiRecommended = container.querySelector('#ai-recommended');
    const calculationDetails = container.querySelector('#calculation-details');

    aiRecommended.value = finalOrderQuantity;

    calculationDetails.innerHTML = `
      <div style="background: var(--bg-main); padding: 15px; border-radius: 4px;">
        <h4>計算詳細</h4>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 10px; font-size: 14px;">
          <div>基本需要予測: ${baseDemand}個</div>
          <div>調整後需要: ${Math.ceil(adjustedDemand)}個</div>
          <div>リードタイム期間需要: ${Math.ceil(leadTimeDemand)}個</div>
          <div>現在在庫: ${currentStock}個</div>
          <div>安全在庫: ${safetyStock}個</div>
          <div>発注単位: ${orderUnit}個</div>
          <div>最小発注数量: ${minOrderQty}個</div>
          <div><strong>最終発注量: ${finalOrderQuantity}個</strong></div>
        </div>
      </div>
    `;

    resultDiv.style.display = 'block';
  }

  // 初期化
  loadStores();

  // 影響度スライダーの値表示更新
  container.querySelector('#weather-impact').addEventListener('input', (e) => {
    container.querySelector('#weather-value').textContent = e.target.value;
  });

  container.querySelector('#event-impact').addEventListener('input', (e) => {
    container.querySelector('#event-value').textContent = e.target.value;
  });

  // 商品検索
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const searchText = container.querySelector('#product-search').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    const products = await window.aivicApi.list(2); // 商品マスタ
    if (products) {
      let filtered = products.filter(p => p.有効フラグ);

      if (category) {
        filtered = filtered.filter(p => p.商品カテゴリID === category);
      }

      if (searchText) {
        filtered = filtered.filter(p => 
          (p.商品名 && p.商品名.includes(searchText)) ||
          (p.商品コード && p.商品コード.includes(searchText))
        );
      }

      renderProducts(filtered);
    }
  });

  // AI予測実行
  container.querySelector('#btn-ai-predict').addEventListener('click', async () => {
    const storeId = container.querySelector('#store-select').value;
    const startDate = container.querySelector('#period-start').value;
    const endDate = container.querySelector('#period-end').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!startDate || !endDate) {
      showError('対象期間を設定してください');
      return;
    }

    if (!selectedProduct) {
      showError('商品を選択してください');
      return;
    }

    // 需要予測結果を取得
    const predictions = await window.aivicApi.list(8); // 需要予測結果
    if (predictions) {
      const prediction = predictions.find(p => 
        p.店舗ID === storeId && 
        p.商品ID === selectedProduct.id &&
        p.予測対象日>= startDate && 
        p.予測対象日<= endDate
      );

      if (prediction) {
        showPredictionResult(prediction);
      } else {
        // 予測データがない場合はダミーデータを作成
        const dummyPrediction = {
          予測数量: Math.floor(Math.random() * 200) + 50,
          予測精度: Math.floor(Math.random() * 30) + 70,
          推奨発注数量: Math.floor(Math.random() * 150) + 75,
          予測対象日: startDate
        };
        showPredictionResult(dummyPrediction);
      }
    }
  });

  // 計算実行
  container.querySelector('#btn-calculate').addEventListener('click', () => {
    calculateOrderQuantity();
  });

  // 発注書作成
  container.querySelector('#btn-create-order').addEventListener('click', () => {
    window.showScreen('scr-1778591907544'); // 発注書作成画面
  });

  // 計算結果保存
  container.querySelector('#btn-save-calculation').addEventListener('click', async () => {
    const aiRecommended = container.querySelector('#ai-recommended').value;
    const manualAdjustment = container.querySelector('#manual-adjustment').value;

    if (!selectedProduct) {
      showError('商品が選択されていません');
      return;
    }

    const orderData = {
      店舗ID: container.querySelector('#store-select').value,
      商品ID: selectedProduct.id,
      需要予測結果ID: predictionData ? predictionData.id : null,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + (parseInt(container.querySelector('#lead-time').value) || 7) * 24 * 60 * 60 * 1000).toISOString(),
      発注数量: parseInt(manualAdjustment) || parseInt(aiRecommended) || 0,
      予測数量: parseInt(aiRecommended) || 0,
      発注単価: selectedProduct.単価 || 0,
      発注金額: (parseInt(manualAdjustment) || parseInt(aiRecommended) || 0) * (selectedProduct.単価 || 0),
      発注方法: manualAdjustment ? 'AI推奨修正' : 'AI推奨採用',
      発注ステータス: '計算済み',
      仕入先ID: selectedProduct.仕入先ID || '',
      発注理由: 'AI需要予測による発注量計算',
      自動発注フラグ: false,
      作成者ID: 'current-user',
      更新者ID: 'current-user'
    };

    const saved = await window.aivicApi.save(9, orderData); // 発注データ
    if (saved) {
      alert('計算結果を保存しました');
    }
  });

  // 商品選択
  container.addEventListener('click', async (e) => {
    const selectBtn = e.target.closest('.select-product-btn');
    if (selectBtn) {
      const productId = selectBtn.dataset.id;
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        const product = products.find(p => p.id === productId);
        if (product) {
          showSelectedProduct(product);
          container.querySelector('#product-results').style.display = 'none';
        }
      }
    }
  });

  // 手動調整値のバリデーション
  container.querySelector('#manual-adjustment').addEventListener('input', (e) => {
    const value = parseInt(e.target.value);
    if (value < 0) {
      showError('発注量は0以上の値を入力してください');
      e.target.value = '';
    }
  });

  // 数値入力のバリデーション
  container.querySelector('#current-stock').addEventListener('input', (e) => {
    if (e.target.value && parseInt(e.target.value) < 0) {
      showError('在庫数は0以上の値を入力してください');
      e.target.value = '';
    }
  });

  container.querySelector('#safety-stock').addEventListener('input', (e) => {
    if (e.target.value && isNaN(parseInt(e.target.value))) {
      showError('数値を入力してください');
      e.target.value = '';
    }
  });

  container.querySelector('#lead-time').addEventListener('input', (e) => {
    const value = parseInt(e.target.value);
    if (value && (value < 1 || value > 365)) {
      showError('リードタイムは1日以上365日以下で入力してください');
      e.target.value = '';
    }
  });

  container.querySelector('#seasonal-factor').addEventListener('input', (e) => {
    const value = parseFloat(e.target.value);
    if (value && (value < 0.1 || value > 10)) {
      showError('季節補正係数は0.1以上10以下で入力してください');
      e.target.value = '';
    }
  });
}

function(container, apiUrl, tables) {
  let orderItems = [];
  let allProducts = [];
  let allStores = [];
  let demandPredictions = [];

  // テーブルインデックス
  const STORE_TABLE = 1;
  const PRODUCT_TABLE = 2;
  const DEMAND_PREDICTION_TABLE = 9;
  const ORDER_TABLE = 11;

  // 店舗データを読み込み
  function loadStores() {
    window.aivicApi.list(STORE_TABLE).then(stores => {
      if (stores) {
        allStores = stores;
        const storeSelect = container.querySelector('#store-select');
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
        stores.forEach(store => {
          storeSelect.innerHTML += `<option value="${store.id}">${store.店舗名}</option>`;
        });
      }
    });
  }

  // 商品データを読み込み
  function loadProducts() {
    window.aivicApi.list(PRODUCT_TABLE).then(products => {
      if (products) {
        allProducts = products;
        renderProductTable(products);
      }
    });
  }

  // 需要予測データを読み込み
  function loadDemandPredictions() {
    window.aivicApi.list(DEMAND_PREDICTION_TABLE).then(predictions => {
      if (predictions) {
        demandPredictions = predictions;
      }
    });
  }

  // 商品テーブルを描画
  function renderProductTable(products) {
    const tbody = container.querySelector('#product-tbody');
    tbody.innerHTML = products.map(product => {
      const prediction = demandPredictions.find(p => p.商品ID === product.id);
      const predictedQty = prediction ? prediction.予測数量 : 0;

      return `
        <tr data-product-id="${product.id}">
          <td><input type="checkbox" class="product-checkbox" data-product-id="${product.id}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td class="predicted-qty">${predictedQty}</td>
          <td><input type="number" class="quantity-input" min="0" value="${predictedQty}" data-product-id="${product.id}"></td>
          <td><button class="prediction-btn" data-product-id="${product.id}">予測根拠</button></td>
          <td><button class="inventory-btn" data-product-id="${product.id}">在庫確認</button></td>
          <td><button class="history-btn" data-product-id="${product.id}">過去実績</button></td>
        </tr>
      `;
    }).join('');
  }

  // 発注商品一覧を描画
  function renderOrderItems() {
    const tbody = container.querySelector('#order-items-tbody');
    tbody.innerHTML = orderItems.map(item => `
      <tr data-item-id="${item.id}">
        <td>${item.商品コード}</td>
        <td>${item.商品名}</td>
        <td>¥${item.単価.toLocaleString()}</td>
        <td>${item.発注数量}</td>
        <td>¥${(item.単価 * item.発注数量).toLocaleString()}</td>
        <td><button class="remove-btn" data-item-id="${item.id}">削除</button></td>
      </tr>
    `).join('');

    updateTotalAmount();
  }

  // 発注総額を更新
  function updateTotalAmount() {
    const total = orderItems.reduce((sum, item) => sum + (item.単価 * item.発注数量), 0);
    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // エラーメッセージを表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      showError('発注日付を入力してください');
      return false;
    }

    if (!deliveryDate) {
      showError('納期を指定してください');
      return false;
    }

    if (new Date(deliveryDate) < new Date(orderDate)) {
      showError('納期は発注日より後の日付を指定してください');
      return false;
    }

    if (orderItems.length === 0) {
      showError('発注する商品を選択してください');
      return false;
    }

    // 発注数量のバリデーション
    for (const item of orderItems) {
      if (item.発注数量 <= 0) {
        showError('発注数量は1以上で入力してください');
        return false;
      }
    }

    return true;
  }

  // 初期データ読み込み
  loadStores();
  loadProducts();
  loadDemandPredictions();

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 商品検索
  container.querySelector('#btn-search-product').addEventListener('click', () => {
    const category = container.querySelector('#category-select').value;
    const searchText = container.querySelector('#product-search').value.toLowerCase();

    let filteredProducts = allProducts;

    if (category) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === category);
    }

    if (searchText) {
      filteredProducts = filteredProducts.filter(p => 
        (p.商品名 && p.商品名.toLowerCase().includes(searchText)) ||
        (p.商品コード && p.商品コード.toLowerCase().includes(searchText))
      );
    }

    if (filteredProducts.length === 0 && searchText && !allProducts.some(p => 
      (p.商品名 && p.商品名.toLowerCase().includes(searchText)) ||
      (p.商品コード && p.商品コード.toLowerCase().includes(searchText))
    )) {
      showError('該当する商品が見つかりません');
    }

    renderProductTable(filteredProducts);
  });

  // 商品選択チェックボックスの処理
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('product-checkbox')) {
      const productId = e.target.dataset.productId;
      const product = allProducts.find(p => p.id === productId);
      const quantityInput = container.querySelector(`input.quantity-input[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;

      if (e.target.checked) {
        if (quantity <= 0) {
          showError('発注数量は1以上で入力してください');
          e.target.checked = false;
          return;
        }

        // 発注リストに追加
        const orderItem = {
          id: productId,
          商品コード: product.商品コード,
          商品名: product.商品名,
          単価: product.単価,
          発注数量: quantity
        };

        if (!orderItems.find(item => item.id === productId)) {
          orderItems.push(orderItem);
          renderOrderItems();
        }
      } else {
        // 発注リストから削除
        orderItems = orderItems.filter(item => item.id !== productId);
        renderOrderItems();
      }
    }
  });

  // 数量変更の処理
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('quantity-input')) {
      const productId = e.target.dataset.productId;
      const quantity = parseInt(e.target.value) || 0;

      if (quantity < 0) {
        showError('発注数量は正の値を入力してください');
        e.target.value = 0;
        return;
      }

      // 発注リスト内の数量を更新
      const orderItem = orderItems.find(item => item.id === productId);
      if (orderItem) {
        orderItem.発注数量 = quantity;
        renderOrderItems();
      }
    }
  });

  // 発注書作成
  container.querySelector('#btn-create-order').addEventListener('click', async () => {
    if (!validateForm()) return;

    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    try {
      // 各商品の発注データを作成
      for (const item of orderItems) {
        const orderData = {
          店舗ID: storeId,
          商品ID: item.id,
          発注日: orderDate,
          納期予定日: deliveryDate,
          発注数量: item.発注数量,
          発注単価: item.単価,
          発注金額: item.単価 * item.発注数量,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          自動発注フラグ: false,
          作成者ID: 'current-user-id',
          更新者ID: 'current-user-id'
        };

        await window.aivicApi.save(ORDER_TABLE, orderData);
      }

      alert('発注書が正常に作成されました');
      window.showScreen('scr-1778591852463'); // 発注管理画面へ遷移

    } catch (error) {
      showError('発注書の作成に失敗しました');
    }
  });

  // キャンセル
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    window.showScreen('scr-1778591852463'); // 発注管理画面へ遷移
  });

  // モーダル関連のイベント処理
  container.addEventListener('click', (e) => {
    // 予測根拠表示
    if (e.target.classList.contains('prediction-btn')) {
      const productId = e.target.dataset.productId;
      const product = allProducts.find(p => p.id === productId);
      const prediction = demandPredictions.find(p => p.商品ID === productId);

      const modal = container.querySelector('#prediction-modal');
      const details = container.querySelector('#prediction-details');

      details.innerHTML = `
        <h4>${product.商品名}</h4>
        <p><strong>予測数量:</strong> ${prediction ? prediction.予測数量 : 0}</p>
        <p><strong>予測精度:</strong> ${prediction ? prediction.予測精度 : 0}%</p>
        <p><strong>予測モデル:</strong> ${prediction ? prediction.予測モデルバージョン : 'N/A'}</p>
        <p><strong>推奨発注数量:</strong> ${prediction ? prediction.推奨発注数量 : 0}</p>
        <div class="muted">
          <p>この予測は過去の売上データ、季節要因、天候データなどを総合的に分析して算出されています。</p>
        </div>
      `;

      modal.classList.remove('hidden');
    }

    // 在庫状況確認
    if (e.target.classList.contains('inventory-btn')) {
      const productId = e.target.dataset.productId;
      const product = allProducts.find(p => p.id === productId);

      const modal = container.querySelector('#inventory-modal');
      const details = container.querySelector('#inventory-details');

      details.innerHTML = `
        <h4>${product.商品名}</h4>
        <p><strong>現在庫数:</strong> ${Math.floor(Math.random() * 100) + 10}個</p>
        <p><strong>安全在庫数:</strong> ${product.最小発注数量 || 10}個</p>
        <p><strong>リードタイム:</strong> ${product.リードタイム日数 || 3}日</p>
        <p><strong>最小発注数量:</strong> ${product.最小発注数量 || 1}個</p>
        <div class="muted">
          <p>在庫状況を考慮して適切な発注数量を決定してください。</p>
        </div>
      `;

      modal.classList.remove('hidden');
    }

    // 過去実績参照
    if (e.target.classList.contains('history-btn')) {
      const productId = e.target.dataset.productId;
      const product = allProducts.find(p => p.id === productId);

      const modal = container.querySelector('#history-modal');
      const details = container.querySelector('#history-details');

      // サンプルの過去実績データ
      const historyData = [
        { 月: '2024年1月', 発注量: 50, 売上量: 48 },
        { 月: '2024年2月', 発注量: 45, 売上量: 43 },
        { 月: '2024年3月', 発注量: 60, 売上量: 58 }
      ];

      details.innerHTML = `
        <h4>${product.商品名} - 過去3ヶ月実績</h4>
        <table class="table">
          <thead>
            <tr><th>月</th><th>発注量</th><th>売上量</th><th>消化率</th></tr>
          </thead>
          <tbody>
            ${historyData.map(data => `
              <tr>
                <td>${data.月}</td>
                <td>${data.発注量}</td>
                <td>${data.売上量}</td>
                <td>${Math.round((data.売上量 / data.発注量) * 100)}%</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
        <div class="muted">
          <p>過去の実績を参考に発注数量を調整してください。</p>
        </div>
      `;

      modal.classList.remove('hidden');
    }

    // 発注商品削除
    if (e.target.classList.contains('remove-btn')) {
      const itemId = e.target.dataset.itemId;
      orderItems = orderItems.filter(item => item.id !== itemId);

      // 対応するチェックボックスのチェックを外す
      const checkbox = container.querySelector(`input.product-checkbox[data-product-id="${itemId}"]`);
      if (checkbox) {
        checkbox.checked = false;
      }

      renderOrderItems();
    }

    // モーダルを閉じる
    if (e.target.id === 'close-prediction-modal') {
      container.querySelector('#prediction-modal').classList.add('hidden');
    }
    if (e.target.id === 'close-inventory-modal') {
      container.querySelector('#inventory-modal').classList.add('hidden');
    }
    if (e.target.id === 'close-history-modal') {
      container.querySelector('#history-modal').classList.add('hidden');
    }
  });

  // モーダル背景クリックで閉じる
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('modal')) {
      e.target.classList.add('hidden');
    }
  });
}

function(container, apiUrl, tables) {
