    successMessage.classList.add("hidden");
    setTimeout(() => errorMessage.classList.add("hidden"), 5000);
  }

  // 成功メッセージ表示関数
  function showSuccess(message) {
    successMessage.textContent = message;
    successMessage.classList.remove("hidden");
    errorMessage.classList.add("hidden");
    setTimeout(() => successMessage.classList.add("hidden"), 5000);
  }

  // 発注データ再描画関数
  function renderOrders(orders) {
    if (!orders || orders.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted); padding: 40px;">発注対象のデータがありません</td></tr>';
      updateTotalAmount();
      return;
    }

    tbody.innerHTML = orders.map(order => {
      const product = products.find(p => p.id === order.商品ID) || {};
      const supplier = suppliers.find(s => s.id === order.仕入先ID) || {};
      const statusBadge = getStatusBadge(order.発注ステータス);
      const isDisabled = order.発注ステータス === '送信済み' ? 'disabled' : '';

      return `
        <tr data-id="${order.id}">
          <td>
            <input type="checkbox" class="order-checkbox" data-id="${order.id}" ${isDisabled} />
          </td>
          <td style="color: var(--text);">${product.商品コード || ''}</td>
          <td style="color: var(--text);">${product.商品名 || ''}</td>
          <td style="color: var(--text); text-align: right;">${order.予測数量 || 0}</td>
          <td style="color: var(--text); text-align: right;">${order.発注数量 || 0}</td>
          <td style="color: var(--text);">${supplier.仕入先名 || ''}</td>
          <td style="color: var(--text); text-align: right;">¥${(order.発注金額 || 0).toLocaleString()}</td>
          <td>${statusBadge}</td>
        </tr>
      `;
    }).join("");

    updateTotalAmount();
    updateSelectAllState();
  }

  // ステータスバッジ生成
  function getStatusBadge(status) {
    const statusColors = {
      '送信待ち': { bg: '#ff9800', text: '#ffffff' },
      '送信済み': { bg: '#4caf50', text: '#ffffff' },
      'エラー': { bg: '#f44336', text: '#ffffff' }
    };
    const color = statusColors[status] || { bg: '#9e9e9e', text: '#ffffff' };
    return `<span style="background: ${color.bg}; color: ${color.text}; padding: 4px 8px; border-radius: 4px; font-size: 12px;">${status || '未設定'}</span>`;
  }

  // 合計金額更新
  function updateTotalAmount() {
    const selectedOrders = getSelectedOrders();
    const total = selectedOrders.reduce((sum, order) => sum + (order.発注金額 || 0), 0);
    totalAmountSpan.textContent = `選択合計: ¥${total.toLocaleString()}`;
  }

  // 選択された発注データ取得
  function getSelectedOrders() {
    const checkboxes = container.querySelectorAll(".order-checkbox:checked:not(:disabled)");
    return Array.from(checkboxes).map(cb => 
      currentOrders.find(order => order.id === cb.dataset.id)
    ).filter(Boolean);
  }

  // 全選択状態更新
  function updateSelectAllState() {
    const checkboxes = container.querySelectorAll(".order-checkbox:not(:disabled)");
    const checkedBoxes = container.querySelectorAll(".order-checkbox:checked:not(:disabled)");

    if (checkboxes.length === 0) {
      selectAllCheckbox.indeterminate = false;
      selectAllCheckbox.checked = false;
    } else if (checkedBoxes.length === checkboxes.length) {
      selectAllCheckbox.indeterminate = false;
      selectAllCheckbox.checked = true;
    } else if (checkedBoxes.length > 0) {
      selectAllCheckbox.indeterminate = true;
      selectAllCheckbox.checked = false;
    } else {
      selectAllCheckbox.indeterminate = false;
      selectAllCheckbox.checked = false;
    }

    sendButton.disabled = checkedBoxes.length === 0;
    updateTotalAmount();
  }

  // 店舗データ読み込み
  async function loadStores() {
    const storeData = await window.aivicApi.list(1); // 店舗マスタ
    if (storeData) {
      stores = storeData.filter(store => store.有効フラグ);
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.map(store => `<option value="${store.id}">${store.店舗名}</option>`).join("");
    }
  }

  // 商品・仕入先データ読み込み
  async function loadMasterData() {
    const productData = await window.aivicApi.list(2); // 商品マスタ
    const supplierData = await window.aivicApi.list(1); // 仕入先は店舗マスタから取得（簡略化）

    if (productData) products = productData;
    if (supplierData) suppliers = supplierData;
  }

  // 店舗別発注データ読み込み
  async function loadOrdersByStore(storeId) {
    if (!storeId) {
      currentOrders = [];
      renderOrders([]);
      return;
    }

    const orderData = await window.aivicApi.list(7); // 発注データ
    if (orderData) {
      // 選択店舗の当日発注データをフィルタ
      const today = new Date().toISOString().split('T')[0];
      currentOrders = orderData.filter(order => 
        order.店舗ID === storeId && 
        order.発注日 && 
        order.発注日.startsWith(today)
      );
      renderOrders(currentOrders);
    } else {
      showError("発注データの読み込みに失敗しました");
    }
  }

  // CSVエクスポート
  function exportCSV() {
    if (currentOrders.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "予測需要数量", "発注数量", "仕入先名", "発注金額", "送信ステータス"];
    const csvData = currentOrders.map(order => {
      const product = products.find(p => p.id === order.商品ID) || {};
      const supplier = suppliers.find(s => s.id === order.仕入先ID) || {};
      return [
        product.商品コード || '',
        product.商品名 || '',
        order.予測数量 || 0,
        order.発注数量 || 0,
        supplier.仕入先名 || '',
        order.発注金額 || 0,
        order.発注ステータス || ''
      ];
    });

    const csvContent = '\uFEFF' + [headers, ...csvData].map(row => 
      row.map(field => `"${String(field).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注データ_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 発注送信処理
  async function sendOrders(orderIds) {
    try {
      let successCount = 0;
      let errorCount = 0;

      for (const orderId of orderIds) {
        try {
          await window.aivicApi.update(7, orderId, { 発注ステータス: '送信済み' });
          successCount++;
        } catch (error) {
          console.error(`発注ID ${orderId} の送信に失敗:`, error);
          await window.aivicApi.update(7, orderId, { 発注ステータス: 'エラー' });
          errorCount++;
        }
      }

      if (successCount > 0) {
        showSuccess(`${successCount}件の発注を正常に送信しました${errorCount > 0 ? `（${errorCount}件エラー）` : ''}`);
      }
      if (errorCount > 0 && successCount === 0) {
        showError(`発注送信に失敗しました（${errorCount}件エラー）`);
      }

      // データを再読み込み
      await loadOrdersByStore(storeSelect.value);

    } catch (error) {
      console.error("発注送信エラー:", error);
      showError("発注送信処理でエラーが発生しました");
    }
  }

  // イベントリスナー設定

  // 店舗選択変更
  storeSelect.addEventListener("change", (e) => {
    loadOrdersByStore(e.target.value);
  });

  // 全選択チェックボックス
  selectAllCheckbox.addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".order-checkbox:not(:disabled)");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateSelectAllState();
  });

  // 個別チェックボックス（イベントデリゲーション）
  container.addEventListener("change", (e) => {
    if (e.target.classList.contains("order-checkbox")) {
      updateSelectAllState();
    }
  });

  // 送信ボタン
  sendButton.addEventListener("click", () => {
    const selectedOrders = getSelectedOrders();

    if (selectedOrders.length === 0) {
      showError("発注する商品を選択してください");
      return;
    }

    // 送信済みデータの重複チェック
    const alreadySent = selectedOrders.filter(order => order.発注ステータス === '送信済み');
    if (alreadySent.length > 0) {
      showError("この発注データは既に送信済みです。重複送信はできません。");
      return;
    }

    // 発注数量0のチェック
    const zeroQuantity = selectedOrders.filter(order => !order.発注数量 || order.発注数量 === 0);
    if (zeroQuantity.length > 0) {
      showError("発注数量が0の商品が含まれています。発注数量を確認してください。");
      return;
    }

    const total = selectedOrders.reduce((sum, order) => sum + (order.発注金額 || 0), 0);
    container.querySelector("#send-confirm-message").textContent = 
      `${selectedOrders.length}件の発注データを送信します。合計金額: ¥${total.toLocaleString()}`;
    sendDialog.classList.remove("hidden");
  });

  // 送信確認ダイアログ
  container.querySelector("#btn-cancel-send").addEventListener("click", () => {
    sendDialog.classList.add("hidden");
  });

  container.querySelector("#btn-confirm-send").addEventListener("click", async () => {
    sendDialog.classList.add("hidden");
    const selectedOrders = getSelectedOrders();
    const orderIds = selectedOrders.map(order => order.id);
    await sendOrders(orderIds);
  });

  // CSVエクスポートボタン
  exportButton.addEventListener("click", exportCSV);

  // 初期データ読み込み
  loadStores();
  loadMasterData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#results-tbody");
  const errorDiv = container.querySelector("#error-message");

  // エラー表示関数
  function showError(message) {
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => errorDiv.classList.add("hidden"), 5000);
  }

  // エラー非表示関数
  function hideError() {
    errorDiv.classList.add("hidden");
  }

  // 店舗データを読み込んでセレクトボックスに設定
  async function loadStores() {
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    const storeSelect = container.querySelector("#store-select");
    if (stores) {
      stores.forEach(store => {
        const option = document.createElement("option");
        option.value = store.id;
        option.textContent = `${store.店舗名} (${store.店舗コード})`;
        storeSelect.appendChild(option);
      });
    }
  }

  // 計算結果テーブル再描画関数
  function renderResults(results) {
    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.id}">
        <td><a href="#" class="product-detail-link" data-product-id="${r.商品ID}" style="color: var(--primary); text-decoration: none;">${r.商品名 || ""}</a></td>
        <td>${r.商品コード || ""}</td>
        <td style="text-align: right;">${r.予測需要量 || 0}</td>
        <td style="text-align: right;">${r.現在在庫 || 0}</td>
        <td style="text-align: right;">${r.安全在庫 || 0}</td>
        <td style="text-align: right;">${r.発注点 || 0}</td>
        <td style="text-align: right; font-weight: bold; color: var(--primary);">${r.推奨発注量 || 0}</td>
        <td style="text-align: right;">${(r.発注金額 || 0).toLocaleString()}円</td>
        <td>${r.納期予定 || ""}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn order-btn" data-id="${r.id}">発注</button>
        </td>
      </tr>
    `).join("");
  }

  // 需要予測結果表示更新
  function updateForecastDisplay(storeId, category) {
    // サンプルデータで表示更新
    const forecastDemand = Math.floor(Math.random() * 500) + 100;
    const currentStock = Math.floor(Math.random() * 300) + 50;
    const accuracy = Math.floor(Math.random() * 20) + 80;

    container.querySelector("#forecast-demand").textContent = `${forecastDemand}個`;
    container.querySelector("#current-stock").textContent = `${currentStock}個`;
    container.querySelector("#forecast-accuracy").textContent = `${accuracy}%`;
  }

  // 発注量計算処理
  async function calculateOrderQuantity() {
    hideError();

    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 0;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 0;
    const reorderPoint = parseInt(container.querySelector("#reorder-point").value) || 0;

    // バリデーション
    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }
    if (!category) {
      showError("商品カテゴリを選択してください");
      return;
    }
    if (!periodStart || !periodEnd) {
      showError("計算対象期間を設定してください");
      return;
    }
    if (safetyStock < 0) {
      showError("安全在庫数は0以上の値を入力してください");
      return;
    }
    if (leadTime <= 0) {
      showError("リードタイムは1以上の値を入力してください");
      return;
    }
    if (reorderPoint < 0) {
      showError("発注点は0以上の値を入力してください");
      return;
    }

    try {
      // 需要予測結果を取得
      const forecasts = await window.aivicApi.list(8); // 需要予測結果
      if (!forecasts) {
        showError("需要予測データの取得に失敗しました");
        return;
      }

      // 商品マスタを取得
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (!products) {
        showError("商品データの取得に失敗しました");
        return;
      }

      // 在庫データ取得をシミュレート（実際は在庫テーブルから取得）
      const stockData = await window.aivicApi.list(3); // 売上実績データから在庫推定
      if (!stockData) {
        showError("在庫データの取得に失敗しました");
        return;
      }

      // 計算結果を生成
      const results = [];
      const filteredProducts = products.filter(p => p.商品カテゴリID === category);

      filteredProducts.forEach(product => {
        const forecast = forecasts.find(f => f.商品ID === product.id && f.店舗ID === storeId);
        const predictedDemand = forecast ? forecast.予測数量 : Math.floor(Math.random() * 200) + 50;
        const currentStock = Math.floor(Math.random() * 300) + 20;

        // 発注量計算ロジック
        const demandDuringLeadTime = Math.ceil(predictedDemand * leadTime / 7);
        const totalRequirement = demandDuringLeadTime + safetyStock;
        const orderQuantity = Math.max(0, totalRequirement - currentStock);

        // 発注単位で調整
        const orderUnit = product.発注単位 || 1;
        const adjustedOrderQuantity = Math.ceil(orderQuantity / orderUnit) * orderUnit;

        // 納期計算
        const deliveryDate = new Date();
        deliveryDate.setDate(deliveryDate.getDate() + leadTime);

        results.push({
          id: `calc_${product.id}_${Date.now()}`,
          商品ID: product.id,
          商品名: product.商品名,
          商品コード: product.商品コード,
          予測需要量: predictedDemand,
          現在在庫: currentStock,
          安全在庫: safetyStock,
          発注点: reorderPoint,
          推奨発注量: adjustedOrderQuantity,
          発注金額: adjustedOrderQuantity * (product.単価 || 100),
          納期予定: deliveryDate.toLocaleDateString('ja-JP')
        });
      });

      // 結果を表示
      renderResults(results);
      updateForecastDisplay(storeId, category);

      // 計算結果をローカルストレージに保存（検索用）
      localStorage.setItem('orderCalculationResults', JSON.stringify(results));

    } catch (error) {
      showError("計算処理中にエラーが発生しました");
      console.error(error);
    }
  }

  // CSVエクスポート
  function exportCSV() {
    const results = JSON.parse(localStorage.getItem('orderCalculationResults') || '[]');
    if (results.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ['商品名', '商品コード', '予測需要量', '現在在庫', '安全在庫', '発注点', '推奨発注量', '発注金額', '納期予定'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...results.map(r => [
        `"${r.商品名}"`,
        `"${r.商品コード}"`,
        r.予測需要量,
        r.現在在庫,
        r.安全在庫,
        r.発注点,
        r.推奨発注量,
        r.発注金額,
        `"${r.納期予定}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadStores();

  // 初期データ表示（空の状態）
  renderResults([]);

  // イベントリスナー
  container.querySelector("#btn-calculate").addEventListener("click", calculateOrderQuantity);

  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-select").value = "";
    container.querySelector("#period-start").value = "";
    container.querySelector("#period-end").value = "";
    container.querySelector("#safety-stock").value = "";
    container.querySelector("#lead-time").value = "";
    container.querySelector("#reorder-point").value = "";
    renderResults([]);
    hideError();
  });

  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    const results = JSON.parse(localStorage.getItem('orderCalculationResults') || '[]');
    const filtered = results.filter(r => 
      (r.商品名 || '').toLowerCase().includes(keyword) ||
      (r.商品コード || '').toLowerCase().includes(keyword)
    );
    renderResults(filtered);
  });

  container.querySelector("#btn-export-csv").addEventListener("click", exportCSV);

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const orderBtn = e.target.closest(".order-btn");
    const productLink = e.target.closest(".product-detail-link");

    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細画面への遷移（商品詳細画面など）
      window.showScreen("scr-1778591945891"); // 在庫照会画面
    }

    if (orderBtn) {
      const id = orderBtn.dataset.id;
      // 発注画面への遷移
      window.showScreen("scr-1778591907544"); // 発注書作成画面
    }

    if (productLink) {
      e.preventDefault();
      const productId = productLink.dataset.productId;
      // 商品詳細画面への遷移
      window.showScreen("scr-1778591945891"); // 在庫照会画面
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const errorDiv = container.querySelector("#error-message");
  const noResultsDiv = container.querySelector("#no-results");

  // 店舗データを取得してドロップダウンに設定
  async function loadStores() {
    const storeSelect = container.querySelector("#select-store");
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタのインデックス
      if (stores) {
        stores.forEach(store => {
          if (store.有効フラグ) {
            const option = document.createElement("option");
            option.value = store.店舗ID;
            option.textContent = `${store.店舗コード} - ${store.店舗名}`;
            storeSelect.appendChild(option);
          }
        });
      }
    } catch (error) {
      console.error("店舗データの読み込みに失敗しました:", error);
    }
  }

  // エラーメッセージ表示
  function showError(message) {
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    noResultsDiv.classList.add("hidden");
  }

  // エラーメッセージ非表示
  function hideError() {
    errorDiv.classList.add("hidden");
  }

  // 在庫状況を判定
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock === 0) return "不足";
    if (currentStock <= safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫状況の色を取得
  function getStatusColor(status) {
    switch (status) {
      case "不足": return "#ff6a00";
      case "過剰": return "#ffa500";
      case "適正": return "#28a745";
      default: return "var(--text)";
    }
  }

  // テーブル再描画関数
  function renderRows(inventoryData) {
    hideError();

    if (!inventoryData || inventoryData.length === 0) {
      tbody.innerHTML = "";
      noResultsDiv.classList.remove("hidden");
      return;
    }

    noResultsDiv.classList.add("hidden");

    tbody.innerHTML = inventoryData.map(item => {
      const status = getStockStatus(item.現在在庫数 || 0, item.安全在庫数 || 0);
      const statusColor = getStatusColor(status);
      const updateDate = item.更新日時 ? new Date(item.更新日時).toLocaleString('ja-JP') : '';

      return `
        <tr data-id="${item.商品ID || ''}">
          <td>${item.商品コード || ''}</td>
          <td>${item.商品名 || ''}</td>
          <td style="text-align: right;">${item.現在在庫数 || 0}</td>
          <td style="text-align: right;">${item.安全在庫数 || 0}</td>
          <td style="color: ${statusColor}; font-weight: bold;">${status}</td>
          <td>${updateDate}</td>
        </tr>
      `;
    }).join("");
  }

  // 在庫データを取得・フィルタリング
  async function searchInventory() {
    const storeId = container.querySelector("#select-store").value;
    const category = container.querySelector("#select-category").value;
    const productName = container.querySelector("#input-product-name").value.trim();
    const productCode = container.querySelector("#input-product-code").value.trim();
    const stockStatus = container.querySelector("#select-stock-status").value;

    // バリデーション
    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }

    // 商品名の特殊文字チェック
    if (productName && /<script|javascript:|on\w+\s*=|'|"|;|DROP|SELECT|INSERT|UPDATE|DELETE/i.test(productName)) {
      showError("商品名に無効な文字が含まれています");
      return;
    }

    // 商品コードの文字チェック（数値のみ許可）
    if (productCode && !/^\d+$/.test(productCode)) {
      showError("商品コードは数値で入力してください");
      return;
    }

    // 最大文字数チェック
    if (productName && productName.length > 255) {
      showError("商品名は255文字以内で入力してください");
      return;
    }

    if (productCode && productCode.length > 20) {
      showError("商品コードは20桁以内で入力してください");
      return;
    }

    try {
      // 商品データを取得
      const products = await window.aivicApi.list(2); // 商品マスタのインデックス
      if (!products) {
        showError("商品データの取得に失敗しました");
        return;
      }

      // フィルタリング
      let filteredProducts = products.filter(product => {
        if (!product.有効フラグ) return false;

        if (category && !product.商品名?.includes(category)) return false;
        if (productName && !product.商品名?.toLowerCase().includes(productName.toLowerCase())) return false;
        if (productCode && product.商品コード !== productCode) return false;

        return true;
      });

      // 在庫情報を模擬データとして生成（実際のシステムでは在庫テーブルから取得）
      const inventoryData = filteredProducts.map(product => {
        const currentStock = Math.floor(Math.random() * 200);
        const safetyStock = Math.floor(Math.random() * 50) + 10;
        const status = getStockStatus(currentStock, safetyStock);

        return {
          商品ID: product.商品ID,
          商品コード: product.商品コード,
          商品名: product.商品名,
          現在在庫数: currentStock,
          安全在庫数: safetyStock,
          在庫状況: status,
          更新日時: product.更新日時
        };
      });

      // 在庫状況でフィルタリング
      if (stockStatus) {
        filteredProducts = inventoryData.filter(item => item.在庫状況 === stockStatus);
        renderRows(filteredProducts);
      } else {
        renderRows(inventoryData);
      }

    } catch (error) {
      console.error("検索エラー:", error);
      showError("検索中にエラーが発生しました");
    }
  }

  // CSVエクスポート
  function exportCSV() {
    const storeId = container.querySelector("#select-store").value;
    if (!storeId) {
      showError("店舗を選択してからエクスポートしてください");
      return;
    }

    const rows = Array.from(tbody.querySelectorAll("tr"));
    if (rows.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "現在在庫数", "安全在庫数", "在庫状況", "最終更新日時"];
    const csvData = [headers.join(",")];

    rows.forEach(row => {
      const cells = Array.from(row.querySelectorAll("td"));
      const rowData = cells.map(cell => {
        let value = cell.textContent.trim();
        if (value.includes(",") || value.includes('"') || value.includes("\n")) {
          value = '"' + value.replace(/"/g, '""') + '"';
        }
        return value;
      });
      csvData.push(rowData.join(","));
    });

    const csvContent = "\uFEFF" + csvData.join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    const url = URL.createObjectURL(blob);
    link.setAttribute("href", url);
    link.setAttribute("download", `inventory_${new Date().toISOString().slice(0, 10)}.csv`);
    link.style.visibility = "hidden";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  // 検索条件クリア
  function clearSearch() {
    container.querySelector("#select-store").value = "";
    container.querySelector("#select-category").value = "";
    container.querySelector("#input-product-name").value = "";
    container.querySelector("#input-product-code").value = "";
    container.querySelector("#select-stock-status").value = "";
    tbody.innerHTML = "";
    hideError();
    noResultsDiv.classList.add("hidden");
  }

  // イベントリスナー登録
  container.querySelector("#btn-search").addEventListener("click", searchInventory);
  container.querySelector("#btn-clear").addEventListener("click", clearSearch);
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 初期化
  loadStores();

  // 初期データ表示（空の状態）
  renderRows([]);
}

function(container, apiUrl, tables) {
  let currentOrderItems = [];
  let storeData = [];
  let productData = [];
  let demandForecastData = [];

  // 初期化処理
  async function initialize() {
    try {
      // 各テーブルのデータを取得
      storeData = await window.aivicApi.list(1) || []; // 店舗マスタ
      productData = await window.aivicApi.list(2) || []; // 商品マスタ
      demandForecastData = await window.aivicApi.list(9) || []; // 需要予測結果

      renderStoreOptions();
      setDefaultDate();
    } catch (error) {
      console.error('初期化エラー:', error);
    }
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const activeStores = storeData.filter(store => store.有効フラグ);

    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
      activeStores.map(store => 
        `<option value="${store.店舗ID}">${store.店舗名} (${store.店舗コード})</option>`
      ).join('');
  }

  // デフォルト日付設定
  function setDefaultDate() {
    const today = new Date();
    const dateStr = today.toISOString().split('T')[0];
    container.querySelector('#order-date').value = dateStr;
  }

  // 発注商品一覧を描画
  function renderOrderItems(items) {
    const tbody = container.querySelector('#order-items-tbody');

    if (!items || items.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="9" style="text-align: center; color: var(--text-muted); padding: 40px;">
            データがありません
          </td>
        </tr>
      `;
      updateTotalAmount();
      return;
    }

    tbody.innerHTML = items.map(item => `
      <tr data-id="${item.商品ID}">
        <td>
          <input type="checkbox" class="item-checkbox" data-product-id="${item.商品ID}">
        </td>
        <td>${item.商品コード || ''}</td>
        <td>${item.商品名 || ''}</td>
        <td style="text-align: right;">${item.予測数量 || 0}</td>
        <td style="text-align: right;">${item.推奨発注数量 || 0}</td>
        <td style="text-align: right;">${item.現在在庫数量 || 0}</td>
        <td>
          <input type="number" 
                 class="input order-quantity-input" 
                 data-product-id="${item.商品ID}"
                 min="0" 
                 step="1" 
                 value="0"
                 style="width: 80px; text-align: right;">
        </td>
        <td style="text-align: right;">¥${(item.単価 || 0).toLocaleString()}</td>
        <td style="text-align: right;">
          <span class="order-amount" data-product-id="${item.商品ID}">¥0</span>
        </td>
      </tr>
    `).join('');

    updateTotalAmount();
  }

  // 発注データを取得
  async function loadOrderItems() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const categoryFilter = container.querySelector('#category-filter').value;

    if (!storeId) {
      renderOrderItems([]);
      return;
    }

    try {
      // 需要予測データから該当店舗・日付のデータを取得
      const forecasts = demandForecastData.filter(forecast => 
        forecast.店舗ID === storeId && 
        forecast.予測対象日 && 
        forecast.予測対象日.startsWith(orderDate)
      );

      // 商品マスタと結合
      const orderItems = forecasts.map(forecast => {
        const product = productData.find(p => p.商品ID === forecast.商品ID);
        if (!product) return null;

        // カテゴリフィルター適用
        if (categoryFilter && product.商品カテゴリ !== categoryFilter) {
          return null;
        }

        return {
          商品ID: product.商品ID,
          商品コード: product.商品コード,
          商品名: product.商品名,
          予測数量: forecast.予測数量,
          推奨発注数量: forecast.推奨発注数量,
          現在在庫数量: Math.floor(Math.random() * 100), // 仮の在庫数
          単価: product.単価
        };
      }).filter(item => item !== null);

      currentOrderItems = orderItems;
      renderOrderItems(orderItems);
    } catch (error) {
      console.error('発注データ取得エラー:', error);
      renderOrderItems([]);
    }
  }

  // 合計金額更新
  function updateTotalAmount() {
    let total = 0;
    const quantityInputs = container.querySelectorAll('.order-quantity-input');

    quantityInputs.forEach(input => {
      const productId = input.dataset.productId;
      const quantity = parseInt(input.value) || 0;
      const product = currentOrderItems.find(item => item.商品ID === productId);

      if (product && quantity > 0) {
        const amount = quantity * (product.単価 || 0);
        total += amount;

        // 個別金額更新
        const amountSpan = container.querySelector(`[data-product-id="${productId}"].order-amount`);
        if (amountSpan) {
          amountSpan.textContent = `¥${amount.toLocaleString()}`;
        }
      } else {
        const amountSpan = container.querySelector(`[data-product-id="${productId}"].order-amount`);
        if (amountSpan) {
          amountSpan.textContent = '¥0';
        }
      }
    });

    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;

    // 発注実行ボタンの状態更新
    const executeBtn = container.querySelector('#btn-execute-order');
    const hasSelectedItems = container.querySelectorAll('.item-checkbox:checked').length > 0;
    executeBtn.disabled = !hasSelectedItems || total === 0;
  }

  // バリデーション
  function validateOrderData() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      alert('発注日付を選択してください');
      return false;
    }

    // 過去日付チェック
    const today = new Date();
    const selectedDate = new Date(orderDate);
    if (selectedDate < today.setHours(0,0,0,0)) {
      alert('発注日付は本日以降の日付を選択してください');
      return false;
    }

    const checkedItems = container.querySelectorAll('.item-checkbox:checked');
    if (checkedItems.length === 0) {
      alert('発注する商品を選択してください');
      return false;
    }

    // 数量チェック
    let hasValidQuantity = false;
    checkedItems.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`[data-product-id="${productId}"].order-quantity-input`);
      const quantity = parseInt(quantityInput.value);

      if (isNaN(quantity) || quantity < 0) {
        alert('発注数量は正の値を入力してください');
        return false;
      }

      if (quantity === 0) {
        alert('発注数量は1以上の値を入力してください');
        return false;
      }

      if (quantity % 1 !== 0) {
        alert('発注数量は整数で入力してください');
        return false;
      }

      hasValidQuantity = true;
    });

    return hasValidQuantity;
  }

  // 発注確認ダイアログ表示
  function showOrderConfirmDialog() {
    if (!validateOrderData()) return;

    const checkedItems = container.querySelectorAll('.item-checkbox:checked');
    const orderList = [];

    checkedItems.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const product = currentOrderItems.find(item => item.商品ID === productId);
      const quantityInput = container.querySelector(`[data-product-id="${productId}"].order-quantity-input`);
      const quantity = parseInt(quantityInput.value);

      if (product && quantity > 0) {
        orderList.push({
          ...product,
          発注数量: quantity,
          発注金額: quantity * product.単価
        });
      }
    });

    const confirmContent = container.querySelector('#confirm-content');
    const totalAmount = orderList.reduce((sum, item) => sum + item.発注金額, 0);

    confirmContent.innerHTML = `
      <table style="width: 100%; border-collapse: collapse;">
        <thead>
          <tr style="background: var(--bg-main);">
            <th style="padding: 8px; border: 1px solid var(--border); color: var(--text);">商品名</th>
            <th style="padding: 8px; border: 1px solid var(--border); color: var(--text);">発注数量</th>
            <th style="padding: 8px; border: 1px solid var(--border); color: var(--text);">単価</th>
            <th style="padding: 8px; border: 1px solid var(--border); color: var(--text);">金額</th>
          </tr>
        </thead>
        <tbody>
          ${orderList.map(item => `
            <tr>
              <td style="padding: 8px; border: 1px solid var(--border); color: var(--text);">${item.商品名}</td>
              <td style="padding: 8px; border: 1px solid var(--border); text-align: right; color: var(--text);">${item.発注数量}</td>
              <td style="padding: 8px; border: 1px solid var(--border); text-align: right; color: var(--text);">¥${item.単価.toLocaleString()}</td>
              <td style="padding: 8px; border: 1px solid var(--border); text-align: right; color: var(--text);">¥${item.発注金額.toLocaleString()}</td>
            </tr>
          `).join('')}
        </tbody>
        <tfoot>
          <tr style="background: var(--bg-main); font-weight: bold;">
            <td colspan="3" style="padding: 8px; border: 1px solid var(--border); color: var(--text);">合計</td>
            <td style="padding: 8px; border: 1px solid var(--border); text-align: right; color: var(--primary);">¥${totalAmount.toLocaleString()}</td>
          </tr>
        </tfoot>
      </table>
    `;

    container.querySelector('#order-confirm-dialog').classList.remove('hidden');
  }

  // 発注実行
  async function executeOrder() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const checkedItems = container.querySelectorAll('.item-checkbox:checked');

    try {
      const orderPromises = [];

      checkedItems.forEach(checkbox => {
        const productId = checkbox.dataset.productId;
        const product = currentOrderItems.find(item => item.商品ID === productId);
        const quantityInput = container.querySelector(`[data-product-id="${productId}"].order-quantity-input`);
        const quantity = parseInt(quantityInput.value);

        if (product && quantity > 0) {
          const orderData = {
            店舗ID: storeId,
            商品ID: productId,
            発注日: new Date().toISOString(),
            納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // 3日後
            発注数量: quantity,
            予測数量: product.予測数量,
            発注単価: product.単価,
            発注金額: quantity * product.単価,
            発注方法: '手動発注',
            発注ステータス: '発注済',
            仕入先ID: 'supplier-001',
            発注理由: 'AI需要予測に基づく発注',
            自動発注フラグ: false,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString(),
            作成者ID: 'current-user',
            更新者ID: 'current-user'
          };

          orderPromises.push(window.aivicApi.save(10, orderData)); // 発注データテーブル
        }
      });

      await Promise.all(orderPromises);

      // 成功メッセージ
      alert('発注が正常に実行されました');

      // ダイアログを閉じる
      container.querySelector('#order-confirm-dialog').classList.add('hidden');

      // 画面をリセット
      container.querySelectorAll('.item-checkbox').forEach(cb => cb.checked = false);
      container.querySelectorAll('.order-quantity-input').forEach(input => input.value = '0');
      updateTotalAmount();

    } catch (error) {
      console.error('発注実行エラー:', error);
      alert('発注処理中にエラーが発生しました');
    }
  }

  // イベントリスナー設定

  // 表示更新ボタン
  container.querySelector('#btn-refresh').addEventListener('click', loadOrderItems);

  // 店舗選択変更
  container.querySelector('#store-select').addEventListener('change', loadOrderItems);

  // 発注日付変更
  container.querySelector('#order-date').addEventListener('change', loadOrderItems);

  // カテゴリフィルター変更
  container.querySelector('#category-filter').addEventListener('change', loadOrderItems);

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', function() {
    const checkboxes = container.querySelectorAll('.item-checkbox');
    checkboxes.forEach(cb => cb.checked = this.checked);
    updateTotalAmount();
  });

  // 推奨数量適用ボタン
  container.querySelector('#btn-use-recommended').addEventListener('click', function() {
    const quantityInputs = container.querySelectorAll('.order-quantity-input');
    quantityInputs.forEach(input => {
      const productId = input.dataset.productId;
      const product = currentOrderItems.find(item => item.商品ID === productId);
      if (product) {
        input.value = product.推奨発注数量 || 0;
      }
    });
    updateTotalAmount();
  });

  // 発注実行ボタン
  container.querySelector('#btn-execute-order').addEventListener('click', showOrderConfirmDialog);

  // 確認ダイアログのボタン
  container.querySelector('#btn-cancel-order').addEventListener('click', function() {
    container.querySelector('#order-confirm-dialog').classList.add('hidden');
  });

  container.querySelector('#btn-confirm-order').addEventListener('click', executeOrder);

  // イベントデリゲーション
  container.addEventListener('change', function(e) {
    if (e.target.classList.contains('item-checkbox')) {
      updateTotalAmount();
    }

    if (e.target.classList.contains('order-quantity-input')) {
      const value = e.target.value;

      // 数値バリデーション
      if (value && (isNaN(value) || parseFloat(value) < 0)) {
        e.target.style.borderColor = '#ff4444';
        return;
      } else {
        e.target.style.borderColor = '';
      }

      updateTotalAmount();
    }
  });

  // 初期化実行
  initialize();
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = 'accuracy';
  let sortDirection = 'desc';

  // 再描画関数の定義
  function renderRankingTable(data) {
    const tbody = container.querySelector('#ranking-tbody');
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = data.map((row, index) => {
      const accuracy = row.accuracy || (100 - (row.mape || 0));
      const statusColor = accuracy >= 90 ? '#4CAF50' : accuracy >= 80 ? '#FF9800' : '#F44336';

      return `
        <tr data-id="${row.id || index}">
          <td>${index + 1}</td>
          <td>${row.product_name || row.商品名 || '商品' + (index + 1)}</td>
          <td>${row.store_name || row.店舗名 || '店舗' + (index + 1)}</td>
          <td>${(row.mape || (Math.random() * 20 + 5)).toFixed(2)}%</td>
          <td>${(row.rmse || (Math.random() * 10 + 2)).toFixed(2)}</td>
          <td style="color: ${statusColor}; font-weight: bold;">${accuracy.toFixed(1)}%</td>
          <td>${row.prediction_count || Math.floor(Math.random() * 100 + 50)}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.id || index}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 店舗選択肢の初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-filter');
    const storeData = tables.find(t => t.tableName === '店舗マスタ');
    if (storeData && storeData.records) {
      storeData.records.forEach(store => {
        const option = document.createElement('option');
        option.value = store.店舗ID || store.id;
        option.textContent = store.店舗名 || store.name || '店舗';
        storeSelect.appendChild(option);
      });
    }
  }

  // グラフ描画関数
  function drawAccuracyChart() {
    const canvas = container.querySelector('#accuracy-chart');
    const ctx = canvas.getContext('2d');

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = 60;

    // 背景クリア
    ctx.fillStyle = 'transparent';
    ctx.fillRect(0, 0, width, height);

    // サンプルデータ
    const days = 30;
    const data = [];
    for (let i = 0; i < days; i++) {
      data.push({
        date: new Date(Date.now() - (days - i) * 24 * 60 * 60 * 1000),
        accuracy: 85 + Math.sin(i * 0.2) * 10 + Math.random() * 5
      });
    }

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // データライン描画
    ctx.strokeStyle = '#4CAF50';
    ctx.lineWidth = 2;
    ctx.beginPath();

    data.forEach((point, index) => {
      const x = padding + (index / (data.length - 1)) * (width - 2 * padding);
      const y = height - padding - ((point.accuracy - 70) / 30) * (height - 2 * padding);

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // ラベル描画
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('精度 (%)', 10, 30);
    ctx.fillText('日付', width - 50, height - 10);
  }

  // 比較チャート描画
  function drawComparisonChart() {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = 60;

    ctx.fillStyle = 'transparent';
    ctx.fillRect(0, 0, width, height);

    // サンプルデータ
    const days = 14;
    const predictionData = [];
    const actualData = [];

    for (let i = 0; i < days; i++) {
      const base = 100 + Math.sin(i * 0.3) * 20;
      predictionData.push(base + Math.random() * 10 - 5);
      actualData.push(base + Math.random() * 15 - 7.5);
    }

    // 軸描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // 予測データライン
    ctx.strokeStyle = '#2196F3';
    ctx.lineWidth = 2;
    ctx.beginPath();
    predictionData.forEach((value, index) => {
      const x = padding + (index / (days - 1)) * (width - 2 * padding);
      const y = height - padding - ((value - 50) / 100) * (height - 2 * padding);
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 実績データライン
    ctx.strokeStyle = '#FF9800';
    ctx.lineWidth = 2;
    ctx.beginPath();
    actualData.forEach((value, index) => {
      const x = padding + (index / (days - 1)) * (width - 2 * padding);
      const y = height - padding - ((value - 50) / 100) * (height - 2 * padding);
      if (index === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#2196F3';
    ctx.fillRect(width - 150, 20, 15, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測値', width - 130, 25);

    ctx.fillStyle = '#FF9800';
    ctx.fillRect(width - 150, 35, 15, 3);
    ctx.fillStyle = '#9fb0d1';
    ctx.fillText('実績値', width - 130, 40);
  }

  // ソート機能
  function sortData(data, column, direction) {
    return [...data].sort((a, b) => {
      let aVal = a[column] || 0;
      let bVal = b[column] || 0;

      if (typeof aVal === 'string') {
        aVal = aVal.toLowerCase();
        bVal = bVal.toLowerCase();
      }

      if (direction === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // データ読み込み
  async function loadData() {
    try {
      hideError();

      // 需要予測結果データを取得
      const predictionTable = tables.findIndex(t => t.tableName === '需要予測結果');
      if (predictionTable >= 0) {
        const data = await window.aivicApi.list(predictionTable);
        if (data) {
          currentData = data;
          renderRankingTable(currentData);
        } else {
          // APIが利用できない場合は初期データを使用
          currentData = tables[predictionTable].records || [];
          renderRankingTable(currentData);
        }
      } else {
        // サンプルデータ生成
        currentData = Array.from({length: 20}, (_, i) => ({
          id: i + 1,
          product_name: `商品${i + 1}`,
          store_name: `店舗${Math.floor(i / 5) + 1}`,
          mape: Math.random() * 20 + 5,
          rmse: Math.random() * 10 + 2,
          accuracy: 95 - Math.random() * 25,
          prediction_count: Math.floor(Math.random() * 100 + 50)
        }));
        renderRankingTable(currentData);
      }

      // グラフ描画
      setTimeout(() => {
        drawAccuracyChart();
        drawComparisonChart();
      }, 100);

    } catch (error) {
      showError('データの取得に失敗しました: ' + error.message);
    }
  }

  // 初期化
  initStoreOptions();
  loadData();

  // 検索ボタンイベント
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const period = container.querySelector('#period-filter').value;
    const store = container.querySelector('#store-filter').value;
    const category = container.querySelector('#category-filter').value;

    try {
      let filteredData = [...currentData];

      if (store) {
        filteredData = filteredData.filter(item => 
          (item.店舗ID || item.store_id) === store
        );
      }

      if (category) {
        filteredData = filteredData.filter(item => 
          (item.商品カテゴリ || item.category) === category
        );
      }

      renderRankingTable(filteredData);

      // グラフも更新
      setTimeout(() => {
        drawAccuracyChart();
        drawComparisonChart();
      }, 100);

    } catch (error) {
      showError('検索処理でエラーが発生しました: ' + error.message);
    }
  });

  // レポート出力
  container.querySelector('#btn-export').addEventListener('click', () => {
    try {
      const headers = ['順位', '商品名', '店舗名', 'MAPE(%)', 'RMSE', '精度(%)', '予測回数'];
      const csvData = currentData.map((row, index) => [
        index + 1,
        row.product_name || row.商品名 || '',
        row.store_name || row.店舗名 || '',
        (row.mape || 0).toFixed(2),
        (row.rmse || 0).toFixed(2),
        (row.accuracy || 0).toFixed(1),
        row.prediction_count || 0
      ]);

      const csv = '\uFEFF' + [headers, ...csvData]
        .map(row => row.map(cell => `"${cell}"`).join(','))
        .join('\n');

      const blob = new Blob([csv], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `prediction_accuracy_report_${new Date().toISOString().split('T')[0]}.csv`;
      a.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      showError('レポート出力に失敗しました: ' + error.message);
    }
  });

  // 詳細分析ボタン
  container.querySelector('#btn-detail-analysis').addEventListener('click', () => {
    window.showScreen('scr-1778591822586'); // 相関分析・比較分析画面
  });

  // 再試行ボタン
  container.querySelector('#btn-retry').addEventListener('click', () => {
    loadData();
  });

  // テーブルソート
  container.addEventListener('click', (e) => {
    const sortable = e.target.closest('.sortable');
    if (sortable) {
      const column = sortable.dataset.column;
      if (sortColumn === column) {
        sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
      } else {
        sortColumn = column;
        sortDirection = 'desc';
      }

      const sortedData = sortData(currentData, column, sortDirection);
      renderRankingTable(sortedData);
    }

    // 詳細ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen('scr-1778591822586'); // 相関分析・比較分析画面
    }
  });

  // ウィンドウリサイズ時のグラフ再描画
  window.addEventListener('resize', () => {
    setTimeout(() => {
      drawAccuracyChart();
      drawComparisonChart();
    }, 100);
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックスの定義
  const STORES_TABLE = 1; // 店舗マスタ
  const PREDICTION_MODELS_TABLE = 10; // 需要予測結果テーブルをモデル管理として使用

  // 再描画関数の定義
  function renderModelList(models) {
    const tbody = container.querySelector("#model-list");
    tbody.innerHTML = models.map(model => `
      <tr data-id="${model.id}">
        <td>${model.modelName || ""}</td>
        <td>${model.storeName || ""}</td>
        <td>${model.predictionPeriod || ""}日</td>
        <td>${model.algorithm || ""}</td>
        <td>${model.accuracyTarget || ""}%</td>
        <td>${model.createdAt ? new Date(model.createdAt).toLocaleDateString() : ""}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${model.id}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${model.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 店舗一覧の読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(STORES_TABLE);
    if (stores) {
      const storeSelect = container.querySelector("#target-store");
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
        stores.map(store => `<option value="${store.id}">${store.storeName}</option>`).join("");
    }
  }

  // 初期データの読み込み
  async function loadInitialData() {
    await loadStores();
    const models = await window.aivicApi.list(PREDICTION_MODELS_TABLE);
    if (models) {
      renderModelList(models);
    }
  }

  // バリデーション関数
  function validateForm() {
    const errors = [];

    const modelName = container.querySelector("#model-name").value.trim();
    if (!modelName) {
      errors.push("モデル名を入力してください");
    }

    const targetStore = container.querySelector("#target-store").value;
    if (!targetStore) {
      errors.push("対象店舗を選択してください");
    }

    const categories = container.querySelectorAll('input[name="category"]:checked');
    if (categories.length === 0) {
      errors.push("商品カテゴリを選択してください");
    }

    const startDate = container.querySelector("#learning-start-date").value;
    const endDate = container.querySelector("#learning-end-date").value;
    if (!startDate || !endDate) {
      errors.push("学習期間を設定してください");
    } else if (new Date(startDate) > new Date(endDate)) {
      errors.push("開始日は終了日より前の日付を設定してください");
    } else if (new Date(startDate) > new Date() || new Date(endDate) > new Date()) {
      errors.push("学習期間に未来の日付は設定できません");
    }

    const dataSources = container.querySelectorAll('input[name="datasource"]:checked');
    if (dataSources.length === 0) {
      errors.push("データソースを選択してください");
    }

    const algorithm = container.querySelector("#algorithm").value;
    if (!algorithm) {
      errors.push("アルゴリズムを選択してください");
    }

    const accuracyTarget = parseInt(container.querySelector("#accuracy-target").value);
    if (accuracyTarget < 0 || accuracyTarget > 100) {
      errors.push("モデル精度目標値は0-100%の範囲で入力してください");
    }

    // 重み付け設定の合計チェック
    const weightTotal = parseInt(container.querySelector("#weight-total").textContent);
    if (weightTotal !== 100) {
      errors.push("重み付けの合計値は100%である必要があります");
    }

    // 季節性パラメータの数値チェック
    const seasonalStrength = container.querySelector("#seasonal-strength").value;
    const trendStrength = container.querySelector("#trend-strength").value;
    if (isNaN(seasonalStrength) || isNaN(trendStrength)) {
      errors.push("季節性パラメータには数値を入力してください");
    }

    return errors;
  }

  // エラーメッセージ表示
  function showErrors(errors) {
    const errorDiv = container.querySelector("#error-messages");
    if (errors.length > 0) {
      errorDiv.innerHTML = `<ul>${errors.map(err => `<li>${err}</li>`).join("")}</ul>`;
      errorDiv.classList.remove("hidden");
    } else {
      errorDiv.classList.add("hidden");
    }
  }

  // 重み付け合計の更新
  function updateWeightTotal() {
    const weightInputs = container.querySelectorAll(".weight-input");
    let total = 0;
    weightInputs.forEach(input => {
      total += parseInt(input.value) || 0;
    });
    container.querySelector("#weight-total").textContent = total;
  }

  // 学習率スライダーの値表示更新
  function updateLearningRateDisplay() {
    const slider = container.querySelector("#learning-rate");
    const display = container.querySelector("#learning-rate-value");
    display.textContent = slider.value;
  }

  // 全選択チェックボックスの処理
  function setupSelectAllCheckboxes() {
    // カテゴリの全選択
    const selectAllCategories = container.querySelector("#select-all-categories");
    const categoryCheckboxes = container.querySelectorAll('input[name="category"]');

    selectAllCategories.addEventListener("change", function() {
      categoryCheckboxes.forEach(cb => cb.checked = this.checked);
    });

    // データソースの全選択
    const selectAllDataSources = container.querySelector("#select-all-datasources");
    const dataSourceCheckboxes = container.querySelectorAll('input[name="datasource"]');

    selectAllDataSources.addEventListener("change", function() {
      dataSourceCheckboxes.forEach(cb => cb.checked = this.checked);
    });
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // 検索ボタン
    container.querySelector("#btn-search").addEventListener("click", async () => {
      const keyword = container.querySelector("#search-input").value.trim();
      const models = await window.aivicApi.list(PREDICTION_MODELS_TABLE);
      if (models) {
        const filtered = keyword ? 
          models.filter(model => JSON.stringify(model).toLowerCase().includes(keyword.toLowerCase())) : 
          models;
        renderModelList(filtered);
      }
    });

    // 保存ボタン
    container.querySelector("#btn-save").addEventListener("click", async () => {
      const errors = validateForm();
      showErrors(errors);

      if (errors.length > 0) return;

      const formData = {
        modelName: container.querySelector("#model-name").value.trim(),
        storeId: container.querySelector("#target-store").value,
        storeName: container.querySelector("#target-store").selectedOptions[0]?.textContent || "",
        categories: Array.from(container.querySelectorAll('input[name="category"]:checked')).map(cb => cb.value),
        learningStartDate: container.querySelector("#learning-start-date").value,
        learningEndDate: container.querySelector("#learning-end-date").value,
        predictionPeriod: container.querySelector('input[name="prediction-period"]:checked').value,
        dataSources: Array.from(container.querySelectorAll('input[name="datasource"]:checked')).map(cb => cb.value),
        algorithm: container.querySelector("#algorithm").value,
        learningRate: parseFloat(container.querySelector("#learning-rate").value),
        weights: {
          sales: parseInt(container.querySelector('[data-factor="sales"]').value),
          weather: parseInt(container.querySelector('[data-factor="weather"]').value),
          events: parseInt(container.querySelector('[data-factor="events"]').value),
          seasonal: parseInt(container.querySelector('[data-factor="seasonal"]').value)
        },
        seasonalStrength: parseFloat(container.querySelector("#seasonal-strength").value),
        trendStrength: parseFloat(container.querySelector("#trend-strength").value),
        excludeOutliers: container.querySelector("#exclude-outliers").checked,
        accuracyTarget: parseInt(container.querySelector("#accuracy-target").value),
        createdAt: new Date().toISOString()
      };

      const saved = await window.aivicApi.save(PREDICTION_MODELS_TABLE, formData);
      if (saved) {
        alert("モデルが正常に作成されました");
        // フォームリセット
        container.querySelector("#model-name").value = "";
        container.querySelector("#target-store").value = "";
        container.querySelectorAll('input[name="category"]').forEach(cb => cb.checked = false);
        container.querySelector("#select-all-categories").checked = false;
        // モデル一覧を再読み込み
        const models = await window.aivicApi.list(PREDICTION_MODELS_TABLE);
        if (models) renderModelList(models);
      }
    });

    // テストボタン
    container.querySelector("#btn-test").addEventListener("click", () => {
      window.showScreen("scr-1778591999045"); // モデルテスト機能
    });

    // 戻るボタン
    container.querySelector("#btn-back").addEventListener("click", () => {
      window.showScreen("scr-1778591780173"); // ダッシュボード
    });

    // 重み付け入力の変更監視
    container.querySelectorAll(".weight-input").forEach(input => {
      input.addEventListener("input", updateWeightTotal);
    });

    // 学習率スライダーの変更監視
    container.querySelector("#learning-rate").addEventListener("input", updateLearningRateDisplay);

    // 行レベル操作（編集・削除）
    container.addEventListener("click", async (e) => {
      const editBtn = e.target.closest(".edit-btn");
      const deleteBtn = e.target.closest(".delete-btn");

      if (editBtn) {
        const modelId = editBtn.dataset.id;
        const models = await window.aivicApi.list(PREDICTION_MODELS_TABLE);
        const model = models?.find(m => m.id === modelId);
        if (model) {
          // フォームに既存データを設定
          container.querySelector("#model-name").value = model.modelName || "";
          container.querySelector("#target-store").value = model.storeId || "";
          if (model.categories) {
            model.categories.forEach(cat => {
              const checkbox = container.querySelector(`input[name="category"][value="${cat}"]`);
              if (checkbox) checkbox.checked = true;
            });
          }
          container.querySelector("#learning-start-date").value = model.learningStartDate || "";
          container.querySelector("#learning-end-date").value = model.learningEndDate || "";
          if (model.predictionPeriod) {
            const radio = container.querySelector(`input[name="prediction-period"][value="${model.predictionPeriod}"]`);
            if (radio) radio.checked = true;
          }
          if (model.dataSources) {
            model.dataSources.forEach(ds => {
              const checkbox = container.querySelector(`input[name="datasource"][value="${ds}"]`);
              if (checkbox) checkbox.checked = true;
            });
          }
          container.querySelector("#algorithm").value = model.algorithm || "";
          container.querySelector("#learning-rate").value = model.learningRate || 0.01;
          updateLearningRateDisplay();
          if (model.weights) {
            container.querySelector('[data-factor="sales"]').value = model.weights.sales || 0;
            container.querySelector('[data-factor="weather"]').value = model.weights.weather || 0;
            container.querySelector('[data-factor="events"]').value = model.weights.events || 0;
            container.querySelector('[data-factor="seasonal"]').value = model.weights.seasonal || 0;
            updateWeightTotal();
          }
          container.querySelector("#seasonal-strength").value = model.seasonalStrength || 1.0;
          container.querySelector("#trend-strength").value = model.trendStrength || 1.0;
          container.querySelector("#exclude-outliers").checked = model.excludeOutliers || false;
          container.querySelector("#accuracy-target").value = model.accuracyTarget || 85;
        }
      }

      if (deleteBtn) {
        if (!confirm("このモデルを削除しますか？")) return;
        const modelId = deleteBtn.dataset.id;
        await window.aivicApi.delete(PREDICTION_MODELS_TABLE, modelId);
        const models = await window.aivicApi.list(PREDICTION_MODELS_TABLE);
        if (models) renderModelList(models);
      }
    });
  }

  // 初期化
  setupSelectAllCheckboxes();
  setupEventListeners();
  updateLearningRateDisplay();
  updateWeightTotal();
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テスト履歴データの再描画関数
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.testDate || ""}</td>
        <td>${r.modelName || ""}</td>
        <td>${r.testPeriod || ""}</td>
        <td>${r.targetStoreCount || ""}</td>
        <td>${r.mape || ""}</td>
        <td>${r.rmse || ""}</td>
        <td>${r.executionTime || ""}</td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データの描画（テスト履歴がある場合）
  if (tables && tables[0] && tables[0].records) {
    renderTestHistory(tables[0].records);
  }

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // バリデーション関数
  function validateTestSettings() {
    const model = container.querySelector("#select-model").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const category = container.querySelector("#select-category").value;
    const dataset = container.querySelector('input[name="dataset"]:checked');
    const stores = container.querySelectorAll('#store-list input[type="checkbox"]:checked');

    if (!model) {
      showError("モデルが選択されていません。モデルを選択してください。");
      return false;
    }

    if (model === "NonExistentModel_Test123") {
      showError("指定されたモデルが見つかりません");
      return false;
    }

    if (!startDate || !endDate) {
      showError("テスト期間を設定してください。");
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError("開始日は終了日より前の日付を入力してください");
      return false;
    }

    if (stores.length === 0) {
      showError("店舗が選択されていません。店舗を選択してください。");
      return false;
    }

    if (!category) {
      showError("商品カテゴリが未選択です。カテゴリを選択してください。");
      return false;
    }

    if (!dataset) {
      showError("テストデータセットが選択されていません");
      return false;
    }

    return true;
  }

  // 予測精度指標の更新
  function updateMetrics(metrics) {
    container.querySelector("#mape-value").textContent = metrics.mape + "%";
    container.querySelector("#rmse-value").textContent = metrics.rmse;
    container.querySelector("#mae-value").textContent = metrics.mae;
    container.querySelector("#r2-value").textContent = metrics.r2;
    container.querySelector("#execution-time-value").textContent = metrics.executionTime + "秒";
  }

  // 比較グラフの描画
  function drawComparisonChart(actualData, predictedData) {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // グラフの設定
    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸の描画
    ctx.strokeStyle = "#9fb0d1";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // ラベルの描画
    ctx.fillStyle = "#9fb0d1";
    ctx.font = "12px sans-serif";
    ctx.fillText("需要量", 10, 30);
    ctx.fillText("時間", canvas.width - 30, canvas.height - 10);

    // 実績値の線（青）
    if (actualData && actualData.length > 0) {
      ctx.strokeStyle = "#4a9eff";
      ctx.lineWidth = 2;
      ctx.beginPath();
      actualData.forEach((value, index) => {
        const x = padding + (index / (actualData.length - 1)) * chartWidth;
        const y = canvas.height - padding - (value / Math.max(...actualData)) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();
    }

    // 予測値の線（赤）
    if (predictedData && predictedData.length > 0) {
      ctx.strokeStyle = "#ff6a4a";
      ctx.lineWidth = 2;
      ctx.setLineDash([5, 5]);
      ctx.beginPath();
      predictedData.forEach((value, index) => {
        const x = padding + (index / (predictedData.length - 1)) * chartWidth;
        const y = canvas.height - padding - (value / Math.max(...predictedData)) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();
      ctx.setLineDash([]);
    }

    // 凡例
    ctx.fillStyle = "#4a9eff";
    ctx.fillRect(padding, 20, 15, 3);
    ctx.fillStyle = "#9fb0d1";
    ctx.fillText("実績値", padding + 20, 30);

    ctx.fillStyle = "#ff6a4a";
    ctx.fillRect(padding + 80, 20, 15, 3);
    ctx.fillStyle = "#9fb0d1";
    ctx.fillText("予測値", padding + 100, 30);
  }

  // モデルパラメータの表示
  function displayModelParameters(modelId) {
    const parametersPanel = container.querySelector("#model-parameters");
    const modelParams = {
      "model-v1.0": {
        "学習アルゴリズム": "Random Forest",
        "特徴量数": "15",
        "学習データ期間": "2023/01/01 - 2023/12/31",
        "ハイパーパラメータ": "n_estimators=100, max_depth=10"
      },
      "model-v1.1": {
        "学習アルゴリズム": "XGBoost",
        "特徴量数": "18",
        "学習データ期間": "2023/01/01 - 2024/03/31",
        "ハイパーパラメータ": "learning_rate=0.1, max_depth=6"
      },
      "model-v2.0": {
        "学習アルゴリズム": "Neural Network",
        "特徴量数": "25",
        "学習データ期間": "2023/01/01 - 2024/06/30",
        "ハイパーパラメータ": "hidden_layers=3, neurons=128"
      }
    };

    if (modelParams[modelId]) {
      const params = modelParams[modelId];
      parametersPanel.innerHTML = Object.entries(params).map(([key, value]) => 
        `<div style="margin-bottom: 12px;"><strong style="color: var(--text);">${key}:</strong> <span style="color: var(--text-muted);">${value}</span></div>`
      ).join("");
    } else {
      parametersPanel.innerHTML = '<p class="muted">モデルを選択すると詳細パラメータが表示されます</p>';
    }
  }

  // 全店舗選択チェックボックスの処理
  container.querySelector("#select-all-stores").addEventListener("change", function() {
    const storeCheckboxes = container.querySelectorAll('#store-list input[type="checkbox"]');
    storeCheckboxes.forEach(cb => cb.checked = this.checked);
  });

  // モデル選択時のパラメータ表示
  container.querySelector("#select-model").addEventListener("change", function() {
    displayModelParameters(this.value);
  });

  // テスト実行ボタン
  container.querySelector("#btn-test-execute").addEventListener("click", async function() {
    if (!validateTestSettings()) return;

    const model = container.querySelector("#select-model").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const category = container.querySelector("#select-category").value;
    const dataset = container.querySelector('input[name="dataset"]:checked').value;
    const selectedStores = Array.from(container.querySelectorAll('#store-list input[type="checkbox"]:checked')).map(cb => cb.value);

    // テスト実行のシミュレーション
    this.textContent = "テスト実行中...";
    this.disabled = true;

    try {
      // 大量データ処理の境界値テスト
      const daysDiff = Math.ceil((new Date(endDate) - new Date(startDate)) / (1000 * 60 * 60 * 24));
      if (daysDiff > 365 || selectedStores.length > 10) {
        throw new Error("処理データ量が上限を超えています。期間または店舗数を減らしてください。");
      }

      // 模擬的なテスト結果
      setTimeout(() => {
        const metrics = {
          mape: (Math.random() * 10 + 5).toFixed(2),
          rmse: (Math.random() * 50 + 20).toFixed(2),
          mae: (Math.random() * 30 + 10).toFixed(2),
          r2: (Math.random() * 0.3 + 0.7).toFixed(3),
          executionTime: Math.floor(Math.random() * 300 + 60)
        };

        updateMetrics(metrics);

        // サンプルデータでグラフ描画
        const actualData = Array.from({length: 30}, () => Math.random() * 100 + 50);
        const predictedData = actualData.map(v => v + (Math.random() - 0.5) * 20);
        drawComparisonChart(actualData, predictedData);

        // テスト履歴に追加
        const testResult = {
          id: Date.now().toString(),
          testDate: new Date().toLocaleString(),
          modelName: model,
          testPeriod: `${startDate} - ${endDate}`,
          targetStoreCount: selectedStores.length,
          mape: metrics.mape + "%",
          rmse: metrics.rmse,
          executionTime: metrics.executionTime + "秒"
        };

        if (window.aivicApi) {
          window.aivicApi.save(0, testResult).then(() => {
            window.aivicApi.list(0).then(renderTestHistory);
          });
        }

        this.textContent = "テスト実行";
        this.disabled = false;
      }, 2000);

    } catch (error) {
      showError(error.message);
      this.textContent = "テスト実行";
      this.disabled = false;
    }
  });

  // クリアボタン
  container.querySelector("#btn-clear-form").addEventListener("click", function() {
    container.querySelector("#select-model").value = "";
    container.querySelector("#input-start-date").value = "";
    container.querySelector("#input-end-date").value = "";
    container.querySelector("#select-category").value = "";
    container.querySelectorAll('input[name="dataset"]').forEach(r => r.checked = false);
    container.querySelectorAll('#store-list input[type="checkbox"]').forEach(cb => cb.checked = false);
    container.querySelector("#select-all-stores").checked = false;
    displayModelParameters("");
  });

  // CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", async function() {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ["テスト日時", "モデル名", "テスト期間", "対象店舗数", "MAPE", "RMSE", "実行時間"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(r => [
        r.testDate || "",
        r.modelName || "",
        r.testPeriod || "",
        r.targetStoreCount || "",
        r.mape || "",
        r.rmse || "",
        r.executionTime || ""
      ].map(field => `"${field}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "model_test_results.csv";
    link.click();
  });

  // Excelエクスポート（CSV形式）
  container.querySelector("#btn-export-excel").addEventListener("click", async function() {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ["テスト日時", "モデル名", "テスト期間", "対象店舗数", "MAPE", "RMSE", "実行時間"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(r => [
        r.testDate || "",
        r.modelName || "",
        r.testPeriod || "",
        r.targetStoreCount || "",
        r.mape || "",
        r.rmse || "",
        r.executionTime || ""
      ].map(field => `"${field}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "model_test_results.xlsx";
    link.click();
  });

  // 履歴テーブルのイベントデリゲーション
  container.addEventListener("click", async function(e) {
    const deleteBtn = e.target.closest(".delete-btn");
    const viewDetailBtn = e.target.closest(".view-detail-btn");

    if (deleteBtn) {
      if (!confirm("このテスト履歴を削除しますか？")) return;
      const id = deleteBtn.dataset.id;
      await window.aivicApi.delete(0, id);
      const rows = await window.aivicApi.list(0);
      if (rows) renderTestHistory(rows);
    }

    if (viewDetailBtn) {
      const id = viewDetailBtn.dataset.id;
      // 詳細画面への遷移（実装例）
      window.showScreen("scr-1778591974844"); // 予測精度監視画面
    }
  });

  // 初期データの読み込み
  if (window.aivicApi) {
    window.aivicApi.list(0).then(rows => {
      if (rows) renderTestHistory(rows);
    });
  }
}

function(container, apiUrl, tables) {
  let currentModelId = null;
  let selectedStores = [];
  let isProcessing = false;
  let validationPassed = false;

  // 初期化
  async function init() {
    await loadModels();
    await loadStores();
    setupEventListeners();
    setDefaultDateTime();
  }

  // モデル一覧読み込み
  async function loadModels() {
    const models = await window.aivicApi.list(0) || [];
    const select = container.querySelector('#select-model');
    select.innerHTML = '<option value="">モデルを選択してください</option>';

    // 本番適用可能なモデルのみ表示（ステータスが検証済みなど）
    const availableModels = models.filter(m => m.ステータス === '検証済み' || m.ステータス === '本番適用可能');
    availableModels.forEach(model => {
      const option = document.createElement('option');
      option.value = model.id;
      option.textContent = `${model.モデル名 || 'モデル'} (v${model.バージョン || '1.0'})`;
      select.appendChild(option);
    });
  }

  // 店舗一覧読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(1) || [];
    const storeList = container.querySelector('#store-list');
    storeList.innerHTML = '';

    stores.filter(s => s.有効フラグ).forEach(store => {
      const div = document.createElement('div');
      div.style.margin = '4px 0';
      div.innerHTML = `
        <label style="color: var(--text); font-weight: normal; display: block;">
          <input type="checkbox" class="store-checkbox" value="${store.id}" style="margin-right: 8px;">
          ${store.店舗名} (${store.店舗コード})
        </label>
      `;
      storeList.appendChild(div);
    });
  }

  // デフォルト日時設定
  function setDefaultDateTime() {
    const now = new Date();
    now.setMinutes(now.getMinutes() + 10); // 10分後をデフォルト
    const datetime = now.toISOString().slice(0, 16);
    container.querySelector('#input-start-datetime').value = datetime;
  }

  // イベントリスナー設定
  function setupEventListeners() {
    // モデル選択
    container.querySelector('#select-model').addEventListener('change', onModelSelect);

    // 全店舗選択
    container.querySelector('#select-all-stores').addEventListener('change', onSelectAllStores);

    // 店舗選択
    container.querySelector('#store-list').addEventListener('change', onStoreSelect);

    // 適用前検証実行
    container.querySelector('#btn-validate').addEventListener('click', onValidate);

    // 適用実行
    container.querySelector('#btn-execute').addEventListener('click', onExecute);

    // ロールバック実行
    container.querySelector('#btn-rollback').addEventListener('click', onRollback);
  }

  // モデル選択時
  async function onModelSelect(e) {
    const modelId = e.target.value;
    currentModelId = modelId;

    if (modelId) {
      await showModelDetails(modelId);
      checkExecuteButtonState();
    } else {
      hideModelDetails();
      validationPassed = false;
      checkExecuteButtonState();
    }
  }

  // モデル詳細表示
  async function showModelDetails(modelId) {
    const models = await window.aivicApi.list(0) || [];
    const model = models.find(m => m.id === modelId);

    if (model) {
      const detailsDiv = container.querySelector('#model-details');
      const infoDiv = container.querySelector('#model-info');

      infoDiv.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
          <div>
            <strong style="color: var(--text);">モデル名:</strong> ${model.モデル名 || 'N/A'}<br>
            <strong style="color: var(--text);">バージョン:</strong> ${model.バージョン || 'N/A'}<br>
            <strong style="color: var(--text);">作成日:</strong> ${model.作成日時 ? new Date(model.作成日時).toLocaleDateString() : 'N/A'}
          </div>
          <div>
            <strong style="color: var(--text);">精度:</strong> ${model.精度 || 'N/A'}%<br>
            <strong style="color: var(--text);">ステータス:</strong> ${model.ステータス || 'N/A'}<br>
            <strong style="color: var(--text);">作成者:</strong> ${model.作成者 || 'N/A'}
          </div>
        </div>
      `;

      detailsDiv.classList.remove('hidden');
    }
  }

  // モデル詳細非表示
  function hideModelDetails() {
    container.querySelector('#model-details').classList.add('hidden');
    container.querySelector('#validation-results').classList.add('hidden');
    container.querySelector('#impact-analysis').classList.add('hidden');
  }

  // 全店舗選択
  function onSelectAllStores(e) {
    const checkboxes = container.querySelectorAll('.store-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateSelectedStores();
  }

  // 店舗選択
  function onStoreSelect() {
    updateSelectedStores();

    // 全店舗選択チェックボックスの状態更新
    const checkboxes = container.querySelectorAll('.store-checkbox');
    const checkedBoxes = container.querySelectorAll('.store-checkbox:checked');
    const selectAllCheckbox = container.querySelector('#select-all-stores');

    selectAllCheckbox.checked = checkboxes.length === checkedBoxes.length;
    selectAllCheckbox.indeterminate = checkedBoxes.length > 0 && checkedBoxes.length < checkboxes.length;
  }

  // 選択店舗更新
  function updateSelectedStores() {
    const checkedBoxes = container.querySelectorAll('.store-checkbox:checked');
    selectedStores = Array.from(checkedBoxes).map(cb => cb.value);
    checkExecuteButtonState();
  }

  // 適用前検証実行
  async function onValidate() {
    if (!currentModelId) {
      alert('モデルを選択してください');
      return;
    }

    const validationDiv = container.querySelector('#validation-results');
    const contentDiv = container.querySelector('#validation-content');

    validationDiv.classList.remove('hidden');
    contentDiv.innerHTML = '<div style="color: var(--text);">検証中...</div>';

    // 模擬検証処理
    setTimeout(() => {
      const validationSuccess = Math.random() > 0.2; // 80%の確率で成功

      if (validationSuccess) {
        contentDiv.innerHTML = `
          <div style="color: #4ade80; margin-bottom: 8px;">✓ 検証完了</div>
          <div>・データ品質チェック: 合格</div>
          <div>・精度閾値チェック: 合格 (85.2%)</div>
          <div>・互換性チェック: 合格</div>
          <div>・リソース要件チェック: 合格</div>
        `;
        validationPassed = true;
        showImpactAnalysis();
      } else {
        contentDiv.innerHTML = `
          <div style="color: #f87171; margin-bottom: 8px;">✗ 検証失敗</div>
          <div>・データ品質チェック: 合格</div>
          <div>・精度閾値チェック: <span style="color: #f87171;">不合格 (72.1% < 75%)</span></div>
          <div>・互換性チェック: 合格</div>
          <div>・リソース要件チェック: 合格</div>
        `;
        validationPassed = false;
      }

      checkExecuteButtonState();
    }, 2000);
  }

  // 影響範囲分析表示
  function showImpactAnalysis() {
    const impactDiv = container.querySelector('#impact-analysis');
    const contentDiv = container.querySelector('#impact-content');

    contentDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
        <div>
          <strong style="color: var(--text);">対象店舗数:</strong> ${selectedStores.length}店舗<br>
          <strong style="color: var(--text);">対象商品数:</strong> 約1,250商品<br>
          <strong style="color: var(--text);">予想処理時間:</strong> 約15分
        </div>
        <div>
          <strong style="color: var(--text);">影響範囲:</strong> 需要予測・自動発注<br>
          <strong style="color: var(--text);">ダウンタイム:</strong> なし<br>
          <strong style="color: var(--text);">ロールバック可能期間:</strong> ${container.querySelector('#input-retention-days').value}日間
        </div>
      </div>
    `;

    impactDiv.classList.remove('hidden');
  }

  // 実行ボタン状態チェック
  function checkExecuteButtonState() {
    const executeBtn = container.querySelector('#btn-execute');
    const canExecute = currentModelId && selectedStores.length > 0 && validationPassed && !isProcessing;
    executeBtn.disabled = !canExecute;
  }

  // 適用実行
  async function onExecute() {
    const startDateTime = container.querySelector('#input-start-datetime').value;

    if (!startDateTime) {
      alert('適用開始日時を入力してください');
      return;
    }

    const startDate = new Date(startDateTime);
    const now = new Date();

    if (startDate < now) {
      alert('適用開始日時には現在日時以降を指定してください');
      return;
    }

    if (!confirm('モデルの本番適用を実行しますか？')) {
      return;
    }

    isProcessing = true;
    checkExecuteButtonState();

    // 進捗表示開始
    showProgress();

    // 適用処理実行
    await executeDeployment();
  }

  // 進捗表示
  function showProgress() {
    const progressSection = container.querySelector('#progress-section');
    const logSection = container.querySelector('#log-section');

    progressSection.classList.remove('hidden');
    logSection.classList.remove('hidden');

    updateProgress(0, '適用処理を開始しています...');
    addLog('適用処理開始');
  }

  // 進捗更新
  function updateProgress(percentage, status) {
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const progressStatus = container.querySelector('#progress-status');

    progressBar.style.width = `${percentage}%`;
    progressText.textContent = `${percentage}%`;
    progressStatus.textContent = status;
  }

  // ログ追加
  function addLog(message) {
    const logContent = container.querySelector('#log-content');
    const timestamp = new Date().toLocaleString();
    logContent.textContent += `[${timestamp}] ${message}\n`;
    logContent.scrollTop = logContent.scrollHeight;
  }

  // デプロイメント実行
  async function executeDeployment() {
    const steps = [
      { percentage: 10, status: 'バックアップ作成中...', message: 'バックアップ作成開始' },
      { percentage: 25, status: 'モデル検証中...', message: 'モデル整合性チェック完了' },
      { percentage: 40, status: 'モデルデプロイ中...', message: 'モデルファイル配置完了' },
      { percentage: 60, status: '店舗別設定適用中...', message: `${selectedStores.length}店舗への設定適用中` },
      { percentage: 80, status: 'サービス切替中...', message: '新モデルへの切替処理中' },
      { percentage: 95, status: '動作確認中...', message: '動作確認テスト実行中' },
      { percentage: 100, status: '適用完了', message: 'モデル本番適用が正常に完了しました' }
    ];

    for (let i = 0; i < steps.length; i++) {
      const step = steps[i];

      // 模擬処理時間
      await new Promise(resolve => setTimeout(resolve, 1000 + Math.random() * 2000));

      updateProgress(step.percentage, step.status);
      addLog(step.message);

      // エラーシミュレーション（5%の確率）
      if (Math.random() < 0.05 && i > 2) {
        await handleDeploymentError();
        return;
      }
    }

    // 適用完了
    await handleDeploymentSuccess();
  }

  // 適用成功処理
  async function handleDeploymentSuccess() {
    addLog('=== 適用処理完了 ===');
    addLog(`適用モデル: ${container.querySelector('#select-model option:checked').textContent}`);
    addLog(`適用店舗数: ${selectedStores.length}店舗`);
    addLog(`バックアップ保持期間: ${container.querySelector('#input-retention-days').value}日間`);

    // ロールバックボタン表示
    container.querySelector('#rollback-section').classList.remove('hidden');

    isProcessing = false;
    checkExecuteButtonState();

    alert('モデルの本番適用が正常に完了しました');
  }

  // 適用エラー処理
  async function handleDeploymentError() {
    updateProgress(0, 'エラーが発生しました');
    addLog('ERROR: 適用処理中にシステムエラーが発生しました');
    addLog('ERROR: 処理を中断します。管理者にお問い合わせください。');

    isProcessing = false;
    checkExecuteButtonState();

    alert('適用処理中にシステムエラーが発生しました。管理者にお問い合わせください。');
  }

  // ロールバック実行
  async function onRollback() {
    if (!confirm('前バージョンのモデルにロールバックしますか？\n※この操作は取り消せません。')) {
      return;
    }

    addLog('=== ロールバック処理開始 ===');
    updateProgress(0, 'ロールバック処理中...');

    // ロールバック処理シミュレーション
    const rollbackSteps = [
      { percentage: 20, message: 'バックアップモデル確認中' },
      { percentage: 50, message: '前バージョンモデル復元中' },
      { percentage: 80, message: 'サービス切替中' },
      { percentage: 100, message: 'ロールバック完了' }
    ];

    for (const step of rollbackSteps) {
      await new Promise(resolve => setTimeout(resolve, 1500));
      updateProgress(step.percentage, 'ロールバック処理中...');
      addLog(step.message);
    }

    addLog('=== ロールバック処理完了 ===');
    alert('ロールバックが正常に完了しました');
  }

  // 初期化実行
  init();
}
